namespace Republic.Core.Government.Officials.Models;

/// <summary>
/// Priority urgency tier for Chief of Staff executive recommendations.
/// </summary>
public enum RecommendationPriority
{
    Routine = 0,
    Medium = 1,
    High = 2,
    Critical = 3
}

/// <summary>
/// Lifecycle status of an executive recommendation submitted by the Chief of Staff.
/// </summary>
public enum RecommendationStatus
{
    Pending = 0,
    Accepted = 1,
    Rejected = 2,
    Unresolved = 3
}

/// <summary>
/// Proactive presidential recommendation generated by the Chief of Staff based on actual sovereign country conditions.
/// </summary>
public sealed class ChiefOfStaffRecommendation
{
    public string Id { get; init; } = Guid.NewGuid().ToString("N");
    public string Title { get; set; } = string.Empty;
    public string Summary { get; set; } = string.Empty;
    public string Category { get; set; } = "Executive";
    public RecommendationPriority Priority { get; set; } = RecommendationPriority.Medium;
    public bool IsUrgent { get; set; }
    public RecommendationStatus Status { get; set; } = RecommendationStatus.Pending;
    public string RecommendedAction { get; set; } = string.Empty;
    public double EstimatedCost { get; set; }
    public long CreatedDay { get; set; }
    public ulong CreatedTick { get; set; }
    public long? ResolvedDay { get; set; }
    public string OutcomeMessage { get; set; } = string.Empty;
}
